insert into public.destinations (id, name, region, lat, lon, season, duration, difficulty, budget_per_day_usd, tags, activities, description, tips, sort_order, popularity, zone, day_title, details) values ('bishkek', '{"en":"Bishkek","ru":"Бишкек","ky":"Бишкек"}'::jsonb, 'Chuy', 42.874, 74.59, 'Apr-Oct', '1-2 days', null, 45, array['culture', 'food', 'city']::text[], array['Osh Bazaar walk and street food', 'Ala-Too Square and Oak Park', 'State History Museum']::text[], '{"en":"Leafy capital with Soviet-modernist avenues at the foot of the Kyrgyz Ala-Too range. Your gateway, and the best place in the country to eat."}'::jsonb, array['Yandex Go taxis are cheap and reliable.', 'Bazaars close early on Mondays.']::text[], 0, 0, 'hub', 'Bishkek', '{"altitudeM":800,"history":"Founded as the Kokand fortress of Pishpek in 1825; named Frunze in the Soviet era and Bishkek since 1991.","howToGetThere":"Manas International Airport (FRU) is about 30 km north of the centre; taxis via apps are the simplest transfer."}'::jsonb) on conflict (id) do update set name = excluded.name, details = excluded.details;
insert into public.destinations (id, name, region, lat, lon, season, duration, difficulty, budget_per_day_usd, tags, activities, description, tips, sort_order, popularity, zone, day_title, details) values ('ala-archa', '{"en":"Ala Archa","ru":"Ала-Арча","ky":"Ала-Арча"}'::jsonb, 'Chuy', 42.565, 74.483, 'May-Oct', '1 day', 'Moderate', 30, array['mountains', 'hiking', 'photo']::text[], array['Ak-Sai waterfall trail', 'Gorge walk among juniper forest', 'Views of Korona peak']::text[], '{"en":"National park 40 km south of Bishkek. Juniper-lined gorge, glaciers and 4,000 m peaks within an hour of the city."}'::jsonb, array['Park entry is paid at the gate in cash.', 'Start early; afternoon clouds hide the peaks.']::text[], 1, 4, 'north', 'Ala Archa gorge day hike', '{"altitudeM":2150,"history":"Protected as a national park since 1976.","howToGetThere":"About 40 km south of Bishkek: roughly one hour by taxi or private driver. No regular public transport to the gate.","safety":"Weather changes quickly above the tree line; carry layers and water."}'::jsonb) on conflict (id) do update set name = excluded.name, details = excluded.details;
insert into public.destinations (id, name, region, lat, lon, season, duration, difficulty, budget_per_day_usd, tags, activities, description, tips, sort_order, popularity, zone, day_title, details) values ('issyk-kul', '{"en":"Issyk-Kul (South Shore)","ru":"Иссык-Куль (южный берег)","ky":"Ысык-Көл (түштүк жээк)"}'::jsonb, 'Issyk-Kul', 42.12, 76.99, 'Jun-Sep', '2-3 days', 'Easy', 40, array['lake', 'nomad', 'relax', 'culture', 'photo']::text[], array['Swim at a quiet south-shore beach', 'Walk the shore at sunset', 'Visit a yurt-making workshop village']::text[], '{"en":"The world''s second-largest alpine lake. The south shore is wilder and quieter than the north, with red cliffs, yurt camps and eagle hunters."}'::jsonb, array['Water is coldest in June; best swimming mid-July to August.']::text[], 5.8, 3, 'north', 'Issyk-Kul south shore', '{"altitudeM":1607,"history":"A Silk Road lake; it never freezes despite its altitude because of its mild salinity.","howToGetThere":"South shore villages are 4 to 6 hours from Bishkek by road; shared taxis leave from the Western and Eastern bus stations."}'::jsonb) on conflict (id) do update set name = excluded.name, details = excluded.details;
insert into public.destinations (id, name, region, lat, lon, season, duration, difficulty, budget_per_day_usd, tags, activities, description, tips, sort_order, popularity, zone, day_title, details) values ('cholpon-ata', '{"en":"Cholpon-Ata","ru":"Чолпон-Ата","ky":"Чолпон-Ата"}'::jsonb, 'Issyk-Kul', 42.649, 77.082, 'Jun-Sep', '1-2 days', 'Easy', 55, array['lake', 'relax', 'culture']::text[], array['Petroglyph field walk', 'Beach afternoon', 'Rukh Ordo cultural center']::text[], '{"en":"North-shore resort town on Issyk-Kul, known for Bronze Age petroglyphs and summer beaches."}'::jsonb, array['Busy in late July; book stays ahead.']::text[], 11, 3, 'north', 'Cholpon-Ata and the petroglyphs', '{"altitudeM":1620,"history":"Known for its open-air petroglyph field with carvings from the Bronze Age onward.","howToGetThere":"North shore of Issyk-Kul, about 250 km from Bishkek (around 4 hours)."}'::jsonb) on conflict (id) do update set name = excluded.name, details = excluded.details;
insert into public.destinations (id, name, region, lat, lon, season, duration, difficulty, budget_per_day_usd, tags, activities, description, tips, sort_order, popularity, zone, day_title, details) values ('karakol', '{"en":"Karakol","ru":"Каракол","ky":"Каракол"}'::jsonb, 'Issyk-Kul', 42.49, 78.393, 'Year-round', '2 days', null, 40, array['food', 'culture', 'mountains', 'hiking']::text[], array['Dungan Mosque and wooden Holy Trinity Cathedral', 'Sunday animal market', 'Ashlyan-fu crawl']::text[], '{"en":"Trekking capital of the east, with wooden Russian houses, a Dungan mosque built without nails and the best ashlyan-fu in the country."}'::jsonb, array['Sunday animal market starts at dawn.']::text[], 9, 4, 'north', 'Karakol town', '{"altitudeM":1720,"history":"Founded in 1869 as a Russian military and trading post; home to a wooden Holy Trinity cathedral and the Dungan mosque built without nails.","howToGetThere":"About 400 km from Bishkek via the north shore (6 to 7 hours). Marshrutkas run daily from Bishkek."}'::jsonb) on conflict (id) do update set name = excluded.name, details = excluded.details;
insert into public.destinations (id, name, region, lat, lon, season, duration, difficulty, budget_per_day_usd, tags, activities, description, tips, sort_order, popularity, zone, day_title, details) values ('altyn-arashan', '{"en":"Altyn Arashan","ru":"Алтын-Арашан","ky":"Алтын-Арашан"}'::jsonb, 'Issyk-Kul', 42.372, 78.628, 'Jun-Sep', '1-2 days', 'Moderate', 35, array['mountains', 'horses', 'relax', 'hiking']::text[], array['Hike up the Arashan valley', 'Soak in the hot springs', 'View of Palatka peak']::text[], '{"en":"High valley with natural hot springs under Palatka peak, reached on foot, on horseback or by old Soviet truck."}'::jsonb, array['The road is rough: 4x4 or hike (about 5 hours up).']::text[], 10, 3, 'north', 'Altyn Arashan hot springs', '{"altitudeM":3000,"culture":"Hot-spring valley used by shepherds and trekkers.","howToGetThere":"From Ak-Suu village near Karakol: 4x4 transfer on a rough track, or a 4 to 6 hour hike.","safety":"Altitude around 3,000 m: ascend gradually and carry warm clothing."}'::jsonb) on conflict (id) do update set name = excluded.name, details = excluded.details;
insert into public.destinations (id, name, region, lat, lon, season, duration, difficulty, budget_per_day_usd, tags, activities, description, tips, sort_order, popularity, zone, day_title, details) values ('jeti-oguz', '{"en":"Jeti-Oguz","ru":"Джети-Огуз","ky":"Жети-Өгүз"}'::jsonb, 'Issyk-Kul', 42.335, 78.232, 'May-Oct', '1 day', 'Easy', 30, array['mountains', 'horses', 'photo']::text[], array['Seven Bulls red rocks', 'Broken Heart rock viewpoint', 'Valley of Flowers walk']::text[], '{"en":"Red sandstone cliffs called the Seven Bulls, opening into alpine meadows grazed by horses in summer."}'::jsonb, array['Best light for photos is late afternoon.']::text[], 8, 3, 'north', 'Jeti-Oguz red rocks', '{"altitudeM":2200,"culture":"Named after the red sandstone \"Seven Bulls\" cliffs; the Broken Heart rock is nearby.","howToGetThere":"About 25 km west of Karakol, around 40 minutes by car."}'::jsonb) on conflict (id) do update set name = excluded.name, details = excluded.details;
insert into public.destinations (id, name, region, lat, lon, season, duration, difficulty, budget_per_day_usd, tags, activities, description, tips, sort_order, popularity, zone, day_title, details) values ('song-kul', '{"en":"Song-Kul","ru":"Сон-Куль","ky":"Соң-Көл"}'::jsonb, 'Naryn', 41.83, 75.13, 'Jun-Sep', '2 days', 'Moderate', 35, array['horses', 'nomad', 'mountains', 'photo', 'lake']::text[], array['Evening with a shepherd family', 'Sunrise over the lake', 'Milky Way photography']::text[], '{"en":"Alpine lake at 3,000 m ringed by summer pastures. Herders move up with their yurts from June: the purest nomad experience in the country."}'::jsonb, array['No electricity grid; camps run on solar.', 'Roads open roughly June to September.']::text[], 4, 5, 'north', 'Nights with shepherds at Song-Kul', '{"altitudeM":3016,"culture":"Summer pasture (jailoo) where herders live in yurts from June to September.","howToGetThere":"Via Kochkor on mountain roads, usually passable only in summer; 4x4 recommended.","safety":"No mobile signal; nights can be near freezing even in July."}'::jsonb) on conflict (id) do update set name = excluded.name, details = excluded.details;
insert into public.destinations (id, name, region, lat, lon, season, duration, difficulty, budget_per_day_usd, tags, activities, description, tips, sort_order, popularity, zone, day_title, details) values ('tash-rabat', '{"en":"Tash Rabat","ru":"Таш-Рабат","ky":"Таш-Рабат"}'::jsonb, 'Naryn', 40.823, 75.289, 'Jun-Sep', '1-2 days', 'Moderate', 35, array['culture', 'horses', 'nomad', 'photo']::text[], array['15th-century stone caravanserai', 'Ride toward the Chatyr-Kul pass', 'Yurt night in the valley']::text[], '{"en":"Stone caravanserai on a Silk Road branch, hidden in a quiet valley near the Chinese border."}'::jsonb, array['Remote: combine with Naryn and Chatyr-Kul.']::text[], 5, 2, 'remote', 'Tash Rabat caravanserai', '{"altitudeM":3200,"history":"Stone caravanserai on a branch of the Silk Road, usually dated to the 15th century.","howToGetThere":"About 90 km south of Naryn on the road to the Torugart pass."}'::jsonb) on conflict (id) do update set name = excluded.name, details = excluded.details;
insert into public.destinations (id, name, region, lat, lon, season, duration, difficulty, budget_per_day_usd, tags, activities, description, tips, sort_order, popularity, zone, day_title, details) values ('naryn', '{"en":"Naryn","ru":"Нарын","ky":"Нарын"}'::jsonb, 'Naryn', 41.428, 75.991, 'May-Oct', '1 day', null, 30, array['culture', 'mountains']::text[], array['Walk the Naryn river embankment', 'Regional museum', 'Salkyn-Tor gorge']::text[], '{"en":"Long river town, the practical hub for the inner Tien Shan and the road to Tash Rabat."}'::jsonb, array['Good place to restock cash and fuel.']::text[], 4.6, 1, 'remote', 'Naryn', '{"altitudeM":2040,"howToGetThere":"About 5 hours from Bishkek by road; the base for Tash Rabat and the Torugart road."}'::jsonb) on conflict (id) do update set name = excluded.name, details = excluded.details;
insert into public.destinations (id, name, region, lat, lon, season, duration, difficulty, budget_per_day_usd, tags, activities, description, tips, sort_order, popularity, zone, day_title, details) values ('osh', '{"en":"Osh","ru":"Ош","ky":"Ош"}'::jsonb, 'Osh', 40.513, 72.816, 'Apr-Oct', '2 days', null, 35, array['culture', 'food']::text[], array['Sulaiman-Too sacred mountain', 'Jayma Bazaar', 'Plov lunch']::text[], '{"en":"One of Central Asia''s oldest cities, centered on the UNESCO-listed Sulaiman-Too mountain and a vast bazaar."}'::jsonb, array['Dress modestly at Sulaiman-Too.']::text[], -3, 3, 'south', 'Osh old city', '{"altitudeM":1000,"history":"One of the oldest cities in Central Asia. Sulaiman-Too mountain is a UNESCO World Heritage Site (2009).","howToGetThere":"Daily flights from Bishkek take about an hour; by road it is a long mountain drive of 10 or more hours."}'::jsonb) on conflict (id) do update set name = excluded.name, details = excluded.details;
insert into public.destinations (id, name, region, lat, lon, season, duration, difficulty, budget_per_day_usd, tags, activities, description, tips, sort_order, popularity, zone, day_title, details) values ('arslanbob', '{"en":"Arslanbob","ru":"Арсланбоб","ky":"Арстанбап"}'::jsonb, 'Jalal-Abad', 41.333, 72.933, 'May-Oct', '2 days', 'Moderate', 25, array['hiking', 'mountains', 'food']::text[], array['World''s largest walnut forest', 'Big and small waterfalls', 'Homestay cooking']::text[], '{"en":"Village in the world''s largest wild walnut forest, with waterfalls and community homestays."}'::jsonb, array['Community tourism office arranges guides.']::text[], -2, 2, 'south', 'Arslanbob walnut forest', '{"altitudeM":1600,"culture":"Village surrounded by one of the largest wild walnut forests in the world.","howToGetThere":"From Jalal-Abad by shared taxi, about 2 to 3 hours."}'::jsonb) on conflict (id) do update set name = excluded.name, details = excluded.details;
insert into public.destinations (id, name, region, lat, lon, season, duration, difficulty, budget_per_day_usd, tags, activities, description, tips, sort_order, popularity, zone, day_title, details) values ('sary-chelek', '{"en":"Sary-Chelek","ru":"Сары-Челек","ky":"Сары-Челек"}'::jsonb, 'Jalal-Abad', 41.866, 71.966, 'Jun-Sep', '2 days', 'Moderate', 30, array['lake', 'hiking', 'photo']::text[], array['Lake viewpoint trail', 'Biosphere reserve walk', 'Boat to hidden lakes']::text[], '{"en":"UNESCO biosphere reserve with a deep turquoise lake set in forested mountains."}'::jsonb, array['Reserve fee payable at the entrance.']::text[], -1, 2, 'south', 'Sary-Chelek reserve', '{"altitudeM":1870,"culture":"Lake inside a UNESCO biosphere reserve.","howToGetThere":"Remote: from Jalal-Abad or Tash-Kumyr via Arkyt village; a full day of driving."}'::jsonb) on conflict (id) do update set name = excluded.name, details = excluded.details;
insert into public.destinations (id, name, region, lat, lon, season, duration, difficulty, budget_per_day_usd, tags, activities, description, tips, sort_order, popularity, zone, day_title, details) values ('suusamyr', '{"en":"Suusamyr","ru":"Суусамыр","ky":"Суусамыр"}'::jsonb, 'Chuy', 42.18, 73.95, 'Jun-Sep', '1 day', 'Easy', 30, array['mountains', 'horses', 'nomad']::text[], array['High valley pastures', 'Kumys tasting with herders', 'Too-Ashuu pass drive']::text[], '{"en":"Broad high valley between two ranges, full of summer yurts, on the Bishkek to Osh highway."}'::jsonb, array['Too-Ashuu tunnel can close in bad weather.']::text[], -0.5, 1, 'west', 'Suusamyr valley', '{"altitudeM":2200,"howToGetThere":"High valley on the Bishkek to Osh highway, about 3 hours from Bishkek over the Too-Ashuu pass."}'::jsonb) on conflict (id) do update set name = excluded.name, details = excluded.details;
insert into public.destinations (id, name, region, lat, lon, season, duration, difficulty, budget_per_day_usd, tags, activities, description, tips, sort_order, popularity, zone, day_title, details) values ('skazka', '{"en":"Skazka Canyon","ru":"Каньон Сказка","ky":"Жомок капчыгайы"}'::jsonb, 'Issyk-Kul', 42.159, 77.357, 'May-Oct', 'Half day', 'Easy', 15, array['photo', 'adventure']::text[], array['Scramble the red ridges', 'Lake views from the top', 'Golden-hour photos']::text[], '{"en":"\"Fairy Tale\" canyon: eroded red and ochre ridges a short walk from the lake shore."}'::jsonb, array['Wear shoes with grip; ridges crumble.']::text[], 6.5, 3, 'north', 'Skazka canyon', '{"altitudeM":1700,"culture":"\"Fairy Tale\" canyon of eroded red and orange rock formations.","howToGetThere":"South shore of Issyk-Kul near Tosor village; signposted turn-off from the main road."}'::jsonb) on conflict (id) do update set name = excluded.name, details = excluded.details;
insert into public.destinations (id, name, region, lat, lon, season, duration, difficulty, budget_per_day_usd, tags, activities, description, tips, sort_order, popularity, zone, day_title, details) values ('barskoon', '{"en":"Barskoon","ru":"Барскоон","ky":"Барскоон"}'::jsonb, 'Issyk-Kul', 42.08, 77.6, 'Jun-Sep', '1 day', 'Easy', 25, array['mountains', 'photo', 'hiking']::text[], array['Tears of the Leopard waterfall', 'Gagarin memorial', 'Gorge drive']::text[], '{"en":"Gorge south of the lake with waterfalls and alpine meadows, once a cosmonaut retreat."}'::jsonb, array['Upper gorge road is for 4x4 only.']::text[], 7, 2, 'north', 'Barskoon waterfalls', '{"altitudeM":1900,"howToGetThere":"South shore of Issyk-Kul; the gorge road climbs from Barskoon village to the waterfalls."}'::jsonb) on conflict (id) do update set name = excluded.name, details = excluded.details;
insert into public.destinations (id, name, region, lat, lon, season, duration, difficulty, budget_per_day_usd, tags, activities, description, tips, sort_order, popularity, zone, day_title, details) values ('kel-suu', '{"en":"Kel-Suu","ru":"Кёль-Суу","ky":"Көл-Суу"}'::jsonb, 'Naryn', 41.05, 75.8, 'Jul-Sep', '2 days', 'Hard', 60, array['adventure', 'lake', 'photo']::text[], array['Boat through the flooded canyon', 'Border-zone mountain drive']::text[], '{"en":"Remote lake filling a narrow canyon near the Chinese border. Needs a border permit and a 4x4."}'::jsonb, array['Border permit required, arranged 10+ days ahead.']::text[], 5.3, 1, 'remote', 'Kel-Suu expedition', '{"altitudeM":3500,"howToGetThere":"Remote lake in the Kok-Kiya valley near the Chinese border, usually reached from Naryn region by 4x4 and a final walk or boat.","safety":"Border zone: a permit is required and must be arranged in advance."}'::jsonb) on conflict (id) do update set name = excluded.name, details = excluded.details;
insert into public.destinations (id, name, region, lat, lon, season, duration, difficulty, budget_per_day_usd, tags, activities, description, tips, sort_order, popularity, zone, day_title, details) values ('chatyr-kul', '{"en":"Chatyr-Kul","ru":"Чатыр-Куль","ky":"Чатыр-Көл"}'::jsonb, 'Naryn', 40.62, 75.3, 'Jul-Sep', '1 day', 'Moderate', 30, array['lake', 'photo', 'adventure']::text[], array['Alpine lake at 3,500 m', 'Wildlife and bird watching']::text[], '{"en":"High, windswept lake above Tash Rabat on the old caravan road. Border permit needed."}'::jsonb, array['Permit required; go with a registered operator.']::text[], 5.4, 0, 'remote', 'Chatyr-Kul', '{"altitudeM":3530,"howToGetThere":"Near the Torugart pass beyond Tash Rabat.","safety":"Border zone: a permit is required."}'::jsonb) on conflict (id) do update set name = excluded.name, details = excluded.details;
insert into public.destinations (id, name, region, lat, lon, season, duration, difficulty, budget_per_day_usd, tags, activities, description, tips, sort_order, popularity, zone, day_title, details) values ('konorchek', '{"en":"Konorchek Canyon","ru":"Каньон Конорчек","ky":"Конорчек капчыгайы"}'::jsonb, 'Chuy', 42.55, 75.88, 'Apr-Oct', '1 day', 'Moderate', 20, array['adventure', 'photo', 'hiking']::text[], array['Red canyon hike', 'Towering clay formations']::text[], '{"en":"Deep red canyons near the Boom gorge, spectacular and surprisingly empty."}'::jsonb, array['No water on trail; carry 2 liters.']::text[], 3, 2, 'north', 'Konorchek red canyons', '{"altitudeM":1500,"culture":"Red clay canyons that are popular for day hikes from Bishkek.","howToGetThere":"In the Chuy region near the Boom gorge, about 2 hours east of Bishkek."}'::jsonb) on conflict (id) do update set name = excluded.name, details = excluded.details;
insert into public.destinations (id, name, region, lat, lon, season, duration, difficulty, budget_per_day_usd, tags, activities, description, tips, sort_order, popularity, zone, day_title, details) values ('burana', '{"en":"Burana Tower","ru":"Башня Бурана","ky":"Бурана мунарасы"}'::jsonb, 'Chuy', 42.746, 75.25, 'Year-round', 'Half day', 'Easy', 10, array['culture', 'history', 'photo']::text[], array['11th-century minaret', 'Balbal stone figures', 'Site museum']::text[], '{"en":"Remains of the Karakhanid city of Balasagun: a minaret, balbal stones and a small museum."}'::jsonb, array['On the way from Bishkek to Issyk-Kul.']::text[], 2, 2, 'north', 'Burana Tower', '{"altitudeM":750,"history":"An 11th-century minaret, the remains of the Karakhanid city of Balasagun, with balbal stone figures.","howToGetThere":"About 80 km east of Bishkek near Tokmok; often visited on the way to Issyk-Kul."}'::jsonb) on conflict (id) do update set name = excluded.name, details = excluded.details;
